const SUMMER_SERVICE_PAGES={"1":2,"2":2,"3":2,"4":2,"5":2,"6":2,"7":2,"8":2,"9":2,"10":2,"11":2,"12":3,"13":3,"14":3,"15":3,"16":3,"17":3,"18":3,"19":3,"20":3,"21":3,"22":3,"23":3,"24":3,"25":4,"26":4,"27":4,"28":4,"29":4,"30":4,"31":4,"32":4,"33":4,"34":4,"35":4,"36":4,"37":4,"38":5,"39":5,"40":5,"41":5,"42":5,"43":5,"44":5,"45":5,"46":5,"47":5,"48":5,"49":5,"50":5,"51":6,"52":6,"53":6,"54":6,"55":6,"56":6,"57":6,"58":6,"59":6,"60":6,"61":6,"62":6,"63":6,"64":7,"65":7,"66":7,"67":7,"68":7,"69":7,"70":7,"71":7,"72":7,"73":7,"74":7,"75":7,"76":7,"77":8,"78":8,"79":8,"80":8,"81":8,"82":8,"83":8,"84":8,"85":8,"86":8,"87":8,"88":8,"89":8,"90":9,"91":9,"92":9,"93":9,"94":9,"95":9,"96":9,"97":9,"98":9,"99":9,"100":9,"101":9,"102":9,"103":10,"104":10,"105":10,"106":10,"107":10,"108":10,"109":10,"110":10,"111":10,"112":10,"113":10,"114":10,"115":10,"116":11};
const SUMMER_START=new Date(2026,5,22,0,0,0);
const SUMMER_END=new Date(2026,8,13,23,59,59);
function isSummerServiceDate(d){return d instanceof Date&&!Number.isNaN(d.getTime())&&d>=SUMMER_START&&d<=SUMMER_END;}
function summerServiceDetail(service,day){
 const raw=(SUMMER_SERVICE_RAW[String(service)]||'').trim();
 if(!raw)return 'No hay detalle extraído para este servicio en el Libro de Verano.';
 return '☀️ HORARIO DE VERANO 2026 · Servicio '+service+'\nJornada consultada: '+serviceDayLabel(day)+'\nLa tabla original agrupa LABORABLES / SÁBADOS / DOMINGOS Y FESTIVOS.\n\n'+raw+'\n\nConsulta el PDF de Verano en DOCUMENTOS IMPORTANTES para ver la tabla original.';
}
function serviceSourceText(service,day,d){
 if(isSummerServiceDate(d))return 'Libro de Servicios Verano 2026 · '+serviceDayLabel(day)+' · página '+(SUMMER_SERVICE_PAGES[String(service)]||'—')+' del PDF · entrada en vigor 22/06/2026 · aplicado hasta 13/09/2026';
 const p44=garageMiddayDetail(service,day)?' · asignación salida de garaje: página 44':'';
 return 'Libro de Servicios Invierno 2026-2027 · '+serviceDayLabel(day)+' · página '+(SERVICE_PAGES[service]||'—')+' del PDF'+p44+' · entrada en vigor 14/09/2026';
}

function fmt(d){return new Intl.DateTimeFormat('es-ES',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(d)}
function weekDelta(d){return Math.floor((d-BASE)/(7*86400000));}
function wrap(n){return ((n-1)%TOTAL+TOTAL)%TOTAL+1}
function projected(p,d){
  // Ancla real: semana 14-20/09/2026, conductor 172 (orden 54) = servicio 72 (M).
  // El resto se asigna correlativamente y la rueda avanza +1 servicio cada semana.
  const w=weekDelta(d);
  const anchorWeekService = wrap(ANCHOR_SERVICE + (p.order - ANCHOR_ORDER));
  const srv = wrap(anchorWeekService + direction*w);
  return {service:srv,shift:PROFILE[srv]||p.shift}
}

// --- Asignación efectiva de CORRETURNOS por día -----------------------------
// La rueda conserva el servicio base (p. ej. 103), pero al consultar quién hace
// un servicio concreto se da prioridad al CORRETURNO que lo cubre ese día.
function isCorreturnoService(service){
  const raw=(SERVICE_DETAILS[String(service)]||'').trim();
  return /^CORRETURNO\b/i.test(raw);
}
function weekdayCode(d){
  return ['D','L','M','X','J','V','S'][d.getDay()];
}
function correturnoAssignment(baseService,d){
  const raw=(SERVICE_DETAILS[String(baseService)]||'').trim();
  if(!/^CORRETURNO\b/i.test(raw)) return null;
  // Si es festivo oficial y el propio texto indica que para/descansa, no se
  // adjudica el servicio de día laborable.
  const isoKey=typeof iso==='function'?iso(d):'';
  if(typeof calendarHoliday==='function' && isoKey && calendarHoliday(isoKey) && /festiv(?:o|os).*descansa/i.test(raw)){
    return {kind:'rest',label:'Festivo · descansa',baseService:Number(baseService)};
  }
  const wanted=weekdayCode(d);
  const lines=raw.split(/\n+/).slice(1);
  for(let line of lines){
    line=line.replace(/^\s*\d+\s*[MT]\s*/i,'');
    // Grupos como LMXJ: 62, X J:28, V:Retén o L:RT.
    const re=/(?:^|\s)([LMXJVSD](?:\s*[LMXJVSD]){0,6})\s*:\s*(\d{1,3}|RT|RET[EÉ]N)\b/gi;
    let m;
    while((m=re.exec(line))){
      const days=[...new Set(m[1].toUpperCase().replace(/\s+/g,'').split(''))].join('');
      if(!days.includes(wanted)) continue;
      const value=m[2].toUpperCase();
      if(/^\d+$/.test(value)){
        return {kind:'service',service:Number(value),baseService:Number(baseService),days};
      }
      return {kind:'reten',label:'Retén',baseService:Number(baseService),days};
    }
  }
  return {kind:'rest',label:'Sin servicio asignado por correturno',baseService:Number(baseService)};
}
function effectiveServiceOwner(service,d){
  const n=Number(service);
  // 1) Un correturno que cubre este servicio tiene prioridad absoluta.
  for(const person of PEOPLE){
    const base=projected(person,d);
    const corr=correturnoAssignment(base.service,d);
    if(corr && corr.kind==='service' && Number(corr.service)===n){
      return {person,baseService:Number(base.service),service:n,shift:PROFILE[n]||base.shift,correturno:true};
    }
  }
  // 2) Si nadie lo cubre por correturno, usamos el titular normal, salvo que
  // su propio servicio base sea un CORRETURNO (en cuyo caso no trabaja ese nº).
  for(const person of PEOPLE){
    const base=projected(person,d);
    if(Number(base.service)!==n) continue;
    if(isCorreturnoService(base.service)) continue;
    return {person,baseService:Number(base.service),service:n,shift:base.shift,correturno:false};
  }
  return null;
}
function typeOf(s){s=(s||'').trim(); if(s.startsWith('M'))return'M'; if(s.startsWith('T'))return'T'; return'O'}
function restOf(s){return (s||'').replace(/^\s*[MT]\s*/,'').trim()||'—'}
function badgeClass(s){return typeOf(s).toLowerCase()}
function isRestLike(s){return /\b(SD|JV|LM|MX|XJ|LSD|D)\b|\(|\)/.test(restOf(s))}
function selectedDate(){return new Date(dateEl.value+'T12:00:00')}


function serviceDayForDate(d){
  const dow=d.getDay();
  if(dow===6) return 'sabado';
  if(dow===0) return 'domingo';
  return 'laborable';
}
function serviceDayLabel(day){
  return day==='sabado' ? 'Sábado' : day==='domingo' ? 'Domingo / festivo' : 'Laborable';
}

