function garageMiddayDetail(service,day){
  const map=GARAGE_MIDDAY_BY_DAY[day]||{};
  return (map[String(service)]||'').trim();
}
function detailForServiceDay(service,day,dateContext){
  const d=dateContext instanceof Date?dateContext:selectedDate();
  if(isSummerServiceDate(d))return summerServiceDetail(service,day);
  const rec=SERVICE_BY_DAY[String(service)]||SERVICE_BY_DAY[service];
  const base=rec?(rec[day]||'').trim():'';
  const garage=garageMiddayDetail(service,day);
  const normal=base||(rec?'No figura un horario específico para esta jornada en el Libro de Servicios.':'No hay detalle disponible para este servicio.');
  return garage ? normal+`\n\n🚍 SALIDA DE GARAJE A MEDIODÍA · PÁGINA 44\n${garage}` : normal;
}
function showServiceDay(service,day){
  const d=selectedDate();
  document.querySelectorAll('#serviceDayTabs .serviceDayTab').forEach(b=>b.classList.toggle('active',b.dataset.serviceDay===day));
  $('#serviceDayKind').textContent='Jornada: '+serviceDayLabel(day)+(isSummerServiceDate(d)?' · ☀️ Verano':' · ❄️ Invierno');
  $('#serviceText').textContent=detailForServiceDay(service,day,d);
  $('#serviceSource').textContent=serviceSourceText(service,day,d);
}

