const SERVICE_SHEET_PHOTOS={1:"data:image/jpeg;base64,",2:"data:image/jpeg;base64,",3:"data:image/jpeg;base64,",5:"data:image/jpeg;base64,",6:"data:image/jpeg;base64,",7:"data:image/jpeg;base64,",8:"data:image/jpeg;base64,",10:"data:image/jpeg;base64,",12:"data:image/jpeg;base64,",15:"data:image/jpeg;base64,",16:"data:image/jpeg;base64,",17:"data:image/jpeg;base64,",22:"data:image/jpeg;base64,",23:"data:image/jpeg;base64,",25:"data:image/jpeg;base64,",27:"data:image/jpeg;base64,",30:"data:image/jpeg;base64,",31:"data:image/jpeg;base64,",34:"data:image/jpeg;base64,",36:"data:image/jpeg;base64,",37:"data:image/jpeg;base64,",39:"data:image/jpeg;base64,",40:"data:image/jpeg;base64,",41:"data:image/jpeg;base64,",42:"data:image/jpeg;base64,",43:"data:image/jpeg;base64,",44:"data:image/jpeg;base64,",45:"data:image/jpeg;base64,",46:"data:image/jpeg;base64,",47:"data:image/jpeg;base64,",48:"data:image/jpeg;base64,",49:"data:image/jpeg;base64,",51:"data:image/jpeg;base64,",52:"data:image/jpeg;base64,",53:"data:image/jpeg;base64,",54:"data:image/jpeg;base64,",55:"data:image/jpeg;base64,",57:"data:image/jpeg;base64,",59:"data:image/jpeg;base64,",60:"data:image/jpeg;base64,",62:"data:image/jpeg;base64,",63:"data:image/jpeg;base64,",65:"data:image/jpeg;base64,",66:"data:image/jpeg;base64,",68:"data:image/jpeg;base64,",69:"data:image/jpeg;base64,",71:"data:image/jpeg;base64,",73:"data:image/jpeg;base64,",74:"data:image/jpeg;base64,",75:"data:image/jpeg;base64,",76:"data:image/jpeg;base64,",77:"data:image/jpeg;base64,",78:"data:image/jpeg;base64,",80:"data:image/jpeg;base64,",82:"data:image/jpeg;base64,",85:"data:image/jpeg;base64,",87:"data:image/jpeg;base64,",88:"data:image/jpeg;base64,",96:"data:image/jpeg;base64,",100:"data:image/jpeg;base64,",114:"data:image/jpeg;base64,"};
const SERVICE_SHEET_VARIANTS={74:{laborable:"data:image/jpeg;base64,",sabado:"data:image/jpeg;base64,",domingo:"data:image/jpeg;base64,"}};
function serviceSheetTypeForDate(date){
  const d=date instanceof Date?date:(date?new Date(date):selectedDate());
  const isoDate=iso(d);
  if(d.getDay()===0 || !!calendarHoliday(isoDate)) return 'domingo';
  if(d.getDay()===6) return 'sabado';
  return 'laborable';
}
function serviceSheetFile(service,date){
  const n=Number(service), variants=SERVICE_SHEET_VARIANTS[n];
  if(variants){
    const type=serviceSheetTypeForDate(date);
    return variants[type]||null;
  }
  return SERVICE_SHEET_PHOTOS[n]||null;
}
function openServiceSheetPhoto(service,date){
  const type=serviceSheetTypeForDate(date);
  const file=serviceSheetFile(service,date); if(!file)return;
  const modal=document.getElementById('serviceSheetModal'), img=document.getElementById('serviceSheetImage');
  const label=type==='sabado'?'Sábado':(type==='domingo'?'Domingo/Festivo':'Laborable');
  document.getElementById('serviceSheetModalTitle').textContent='Hoja de ruta · Servicio '+service+' · '+label;
  img.src=file; modal.classList.add('show'); modal.setAttribute('aria-hidden','false');
}
function closeServiceSheetPhoto(){const m=document.getElementById('serviceSheetModal');m.classList.remove('show');m.setAttribute('aria-hidden','true');document.getElementById('serviceSheetImage').src='';}

function renderPersonServiceSheetAction(service,date){
  const box=document.getElementById('personServiceSheetAction');
  if(!box)return;
  const n=Number(service);
  if(serviceSheetFile(n,date)){
    box.innerHTML='<button class="serviceSheetBtn" type="button" id="personServiceSheetBtn">📄 Ver hoja del servicio '+n+'</button>';
    document.getElementById('personServiceSheetBtn').onclick=()=>openServiceSheetPhoto(n,date);
  }else{
    box.innerHTML='<div class="serviceSheetMissing">📄 Hoja del servicio '+n+' no disponible.</div>';
  }
}

function renderServiceSheetAction(service){
  const box=document.getElementById('serviceQuickResult'); if(!box)return;
  let a=document.getElementById('serviceSheetActions'); if(a)a.remove();
  a=document.createElement('div'); a.id='serviceSheetActions'; a.className='serviceSheetActions';
  if(SERVICE_SHEET_PHOTOS[Number(service)]) a.innerHTML='<button class="serviceSheetBtn" type="button" onclick="openServiceSheetPhoto('+Number(service)+')">📄 Ver hoja del servicio '+Number(service)+'</button>';
  else a.innerHTML='<div class="serviceSheetMissing">📄 No hay fotografía de la hoja de este servicio en el ZIP aportado.</div>';
  box.appendChild(a);
}
document.addEventListener('click',e=>{if(e.target&&e.target.id==='serviceSheetClose')closeServiceSheetPhoto();if(e.target&&e.target.id==='serviceSheetModal')closeServiceSheetPhoto();});

function quickServiceSearch(){
  const raw=$('#serviceSearch').value.trim();
  const n=Number(raw);
  const box=$('#serviceQuickResult');
  const personBox=$('#servicePersonResult');

  if(!raw){
    box.classList.remove('show');
    personBox.classList.remove('show');
    return;
  }

  if(!Number.isInteger(n) || n<1 || n>116){
    $('#serviceQuickTitle').textContent='Servicio no válido';
    $('#serviceQuickText').textContent='Introduce un número de servicio entre 1 y 116.';
    box.classList.add('show');
    personBox.classList.remove('show');
    return;
  }

  const qDate=new Date($('#date').value+'T12:00:00');
  const qDay=serviceDayForDate(qDate);
  const detail=detailForServiceDay(n,qDay,qDate);
  $('#serviceQuickTitle').textContent='Servicio '+n+' · '+serviceDayLabel(qDay)+' · '+(isSummerServiceDate(qDate)?'☀️ Verano':'❄️ Invierno');
  $('#serviceQuickText').textContent=detail;
  box.classList.add('show');
  renderServiceSheetAction(n);

  const d=new Date($('#date').value+'T12:00:00');
  const owner=effectiveServiceOwner(n,d);

  if(owner){
    const p=owner.person;
    $('#servicePersonName').textContent=p.name;
    $('#servicePersonMeta').innerHTML=
      `<b>Conductor ${p.driver}</b> · Orden ${p.order} · <b>Servicio ${n}</b> · `+
      `<span class="badge ${badgeClass(owner.shift)}">${owner.shift}</span>`+
      (owner.correturno?` · <b style="color:#7c3aed">CORRETURNO desde servicio ${owner.baseService}</b>`:'')+
      (isDriverOnVacation(p.driver,d) ? ' · <span class="vacBadge">VACACIONES</span>' : '');
    personBox.classList.add('show');
  }else{
    $('#servicePersonName').textContent='Sin conductor asignado';
    $('#servicePersonMeta').textContent='No aparece ningún conductor con este servicio en la fecha seleccionada.';
    personBox.classList.add('show');
  }
}



