const VACATION_VARIABLE_BY_DRIVER={
  '8':'2JUN','37':'1JUL','67':'2JUL','124':'1AGO','153':'2AGO','165':'1SEP',
  '12':'1SEP','26':'2AGO','35':'1AGO','105':'2JUL','138':'1JUL','151':'2JUN','159':'1JUL'
};

function projectedVacationGroup(driver,year){
  const base=VACATION_GROUP_BY_DRIVER[String(driver).trim()];
  if(!base) return null;
  const offset=Number(year)-2026;
  return ((base-1 + offset)%18 + 18)%18 + 1;
}

function vacationPeriodsForDriver(driver,year=2026){
  const key=String(driver).trim();
  const baseGroup=VACATION_GROUP_BY_DRIVER[key];
  if(!baseGroup) return null;

  const group=projectedVacationGroup(key,year);
  let periods=(VACATION_GROUP_PERIODS[group]||[]).slice();

  // El cuadrante 2026 sí concreta la quincena variable de los conductores
  // que pertenecen ese año a los grupos 7 y 13. Para años posteriores,
  // el documento base no permite conocer qué quincena variable concreta
  // corresponderá a los nuevos ocupantes de esos grupos.
  periods=periods.map(code=>{
    if(code!=='VAR') return code;
    if(Number(year)===2026 && VACATION_VARIABLE_BY_DRIVER[key]){
      return VACATION_VARIABLE_BY_DRIVER[key];
    }
    return 'VAR';
  });

  return {baseGroup,group,periods};
}


const VACATION_MONTH_BY_CODE={
  '1ENE':[1], '2ENE':[1],
  '1FEB':[1,2], '2FEB':[2],
  '1MAR':[3], '2MAR':[3],
  '1ABR':[3,4], '2ABR':[4],
  '1MAY':[4,5], '2MAY':[5],
  '1JUN':[6], '2JUN':[6],
  '1JUL':[7], '2JUL':[7],
  '1AGO':[7,8], '2AGO':[8],
  '1SEP':[8,9], '2SEP':[9],
  '1OCT':[9,10], '2OCT':[10],
  '1NOV':[10,11], '2NOV':[11],
  '1DIC':[11,12], '2DIC':[12]
};

function vacationCodeMatchesMonth(code,month){
  if(!month) return true;
  return (VACATION_MONTH_BY_CODE[code]||[]).includes(Number(month));
}

function vacationCodeDateRange(code,year){
  const ranges={
    '1ENE':[[year-1,12,30],[year,1,15]], '2ENE':[[year,1,16],[year,1,30]],
    '1FEB':[[year,1,31],[year,2,14]], '2FEB':[[year,2,15],[year,2,28]],
    '1MAR':[[year,3,1],[year,3,15]], '2MAR':[[year,3,16],[year,3,30]],
    '1ABR':[[year,3,30],[year,4,15]], '2ABR':[[year,4,16],[year,4,30]],
    '1MAY':[[year,4,30],[year,5,15]], '2MAY':[[year,5,16],[year,5,30]],
    '1JUN':[[year,6,1],[year,6,15]], '2JUN':[[year,6,16],[year,6,30]],
    '1JUL':[[year,7,1],[year,7,15]], '2JUL':[[year,7,16],[year,7,30]],
    '1AGO':[[year,7,30],[year,8,15]], '2AGO':[[year,8,16],[year,8,30]],
    '1SEP':[[year,8,31],[year,9,15]], '2SEP':[[year,9,16],[year,9,30]],
    '1OCT':[[year,9,30],[year,10,15]], '2OCT':[[year,10,16],[year,10,30]],
    '1NOV':[[year,10,31],[year,11,15]], '2NOV':[[year,11,16],[year,11,30]],
    '1DIC':[[year,11,29],[year,12,15]], '2DIC':[[year,12,16],[year,12,31]]
  };
  const r=ranges[code];
  if(!r) return null;
  return [new Date(r[0][0],r[0][1]-1,r[0][2],12),new Date(r[1][0],r[1][1]-1,r[1][2],12)];
}

function isDriverOnVacation(driver,date){
  const year=date.getFullYear();
  const data=vacationPeriodsForDriver(driver,year);
  if(!data) return false;
  return data.periods.some(code=>{
    if(code==='VAR') return false;
    const r=vacationCodeDateRange(code,year);
    return r && date>=r[0] && date<=r[1];
  });
}

function openVacationPanel(){
  $('#vacLookupPanel').classList.add('show');
}

function syncVacationsToMainDate(){
  const d=selectedDate();
  if(!d) return;
  openVacationPanel();
  if(d.getFullYear()>=2026 && d.getFullYear()<=2100) $('#vacYearSelect').value=String(d.getFullYear());
  $('#vacMonthSelect').value=String(d.getMonth()+1);
  VACATION_FORTNIGHT=d.getDate()<=15?'1':'2';
  syncVacationFortnightTabs();
  showDriverVacations();
}

let VACATION_FORTNIGHT='1';

function vacationCodeMatchesFortnight(code,half){
  if(!half || code==='VAR') return true;
  return String(code).charAt(0)===String(half);
}

function syncVacationFortnightTabs(){
  const month=$('#vacMonthSelect').value;
  const wrap=$('#vacFortnightTabs');
  if(!wrap) return;
  wrap.classList.toggle('show',!!month);
  wrap.querySelectorAll('.vacFortnightTab').forEach(btn=>{
    const active=btn.dataset.half===VACATION_FORTNIGHT;
    btn.classList.toggle('active',active);
    btn.setAttribute('aria-pressed',active?'true':'false');
  });
}

function personVacationsFiltered(driver,month,year,half=VACATION_FORTNIGHT){
  const data=vacationPeriodsForDriver(driver,year);
  if(!data) return null;
  return {
    baseGroup:data.baseGroup,
    group:data.group,
    periods:data.periods.filter(code=>{
      if(code==='VAR') return !month;
      if(month && !vacationCodeMatchesMonth(code,month)) return false;
      if(month && half && !vacationCodeMatchesFortnight(code,half)) return false;
      return true;
    })
  };
}

function allDriversOnVacationByMonth(month,year){
  const rows=[];
  Object.keys(VACATION_GROUP_BY_DRIVER).forEach(driver=>{
    const data=personVacationsFiltered(driver,month,year);
    if(!data || !data.periods.length) return;
    const person=PEOPLE.find(p=>String(p.driver)===String(driver));
    rows.push({
      driver:String(driver),
      name:person ? person.name : ('Conductor '+driver),
      baseGroup:data.baseGroup,
      group:data.group,
      periods:data.periods
    });
  });
  rows.sort((a,b)=>Number(a.driver)-Number(b.driver));
  return rows;
}

function driversInVacationGroup(group,month,year){
  const rows=[];
  Object.keys(VACATION_GROUP_BY_DRIVER).forEach(driver=>{
    const data=personVacationsFiltered(driver,month,year);
    if(!data || data.group!==Number(group)) return;
    const person=PEOPLE.find(p=>String(p.driver)===String(driver));
    rows.push({driver:String(driver),name:person ? person.name : ('Conductor '+driver),group:data.group,periods:data.periods});
  });
  rows.sort((a,b)=>Number(a.driver)-Number(b.driver));
  return rows;
}

function showDriverVacations(){
  const key=String($('#vacDriverInput').value||'').trim();
  const group=String($('#vacGroupSelect').value||'').trim();
  const month=$('#vacMonthSelect').value;
  const year=Number($('#vacYearSelect').value);
  const box=$('#vacLookupResult');
  syncVacationFortnightTabs();

  if(!$('#vacYearSelect').value || year<2026 || year>2100){
    box.innerHTML='<div class="empty">Selecciona un año entre 2026 y 2100.</div>';
    return;
  }

  // 1) BÚSQUEDA POR Nº DE CONDUCTOR + AÑO.
  // No obliga a escoger mes: muestra sus vacaciones del año completo.
  if(key){
    const data=vacationPeriodsForDriver(key,year);
    const person=PEOPLE.find(p=>String(p.driver)===key);
    if(!data){
      box.innerHTML=`<div class="empty">No hay datos de vacaciones para el conductor ${key}.</div>`;
      return;
    }
    const cards=data.periods.map(code=>{
      if(code==='VAR'){
        return `<div class="vacPeriodCard"><b>QUINCENA VARIABLE</b><span>La quincena concreta debe consultarse en el cuadrante oficial de ${year}.</span></div>`;
      }
      const p=VACATION_PERIODS_2026[code];
      return p ? `<div class="vacPeriodCard"><b>${p.label}</b><span>${p.dates.replace('2026',String(year)).replace('2025',String(year-1))}</span></div>` : '';
    }).join('');
    box.innerHTML=`
      <div class="vacMonthHeading">CONDUCTOR ${key} · ${year}</div>
      <div class="vacPersonRow">
        <div class="who">${person ? person.name : 'Conductor '+key}</div>
        <div class="when"><b>Conductor ${key}</b> · Grupo ${data.group} en ${year}</div>
      </div>
      <div class="vacPeriodGrid">${cards}</div>`;
    return;
  }

  // 2) BÚSQUEDA POR Nº DE GRUPO + AÑO.
  // Devuelve TODOS los conductores que pertenecen a ese grupo en el año elegido.
  // Mes y quincena no reducen este listado.
  if(group){
    const rows=[];
    Object.keys(VACATION_GROUP_BY_DRIVER).forEach(driver=>{
      const data=vacationPeriodsForDriver(driver,year);
      if(!data || data.group!==Number(group)) return;
      const person=PEOPLE.find(p=>String(p.driver)===String(driver));
      rows.push({
        driver:String(driver),
        name:person ? person.name : ('Conductor '+driver),
        group:data.group,
        periods:data.periods
      });
    });
    rows.sort((a,b)=>Number(a.driver)-Number(b.driver));

    box.innerHTML=`
      <div class="vacMonthHeading">GRUPO ${group} · ${year} · ${rows.length} CONDUCTORES</div>
      ${rows.length ? rows.map(r=>{
        const periods=r.periods.map(code=>{
          if(code==='VAR') return 'Quincena variable';
          return VACATION_PERIODS_2026[code]?.label||code;
        }).join(' · ');
        return `<div class="vacPersonRow">
          <div class="who">${r.name}</div>
          <div class="when"><b>Conductor ${r.driver}</b> · Grupo ${r.group} · ${periods}</div>
        </div>`;
      }).join('') : '<div class="empty">No hay conductores asignados a este grupo en el año seleccionado.</div>'}`;
    return;
  }

  // 3) BÚSQUEDA POR MES + AÑO (se conserva como opción adicional).
  if(month){
    const rows=allDriversOnVacationByMonth(month,year);
    const monthText=$('#vacMonthSelect').selectedOptions[0].textContent;
    const fortnightText=VACATION_FORTNIGHT==='1' ? '1ª quincena' : '2ª quincena';
    box.innerHTML=`
      <div class="vacMonthHeading">${monthText} de ${year} · ${fortnightText} · ${rows.length} conductores</div>
      ${rows.length ? rows.map(r=>{
        const periods=r.periods.map(code=>code==='VAR'?'Quincena variable':(VACATION_PERIODS_2026[code]?.label||code)).join(' · ');
        return `<div class="vacPersonRow">
          <div class="who">${r.name}</div>
          <div class="when"><b>Conductor ${r.driver}</b> · Grupo ${r.group} · ${periods}</div>
        </div>`;
      }).join('') : '<div class="empty">No hay resultados para esa selección.</div>'}`;
    return;
  }

  box.innerHTML='<div class="empty">Selecciona un nº de conductor o un nº de grupo y el año, y pulsa BUSCAR.</div>';
}

function restCodeForDay(shift,date){
  const map=['D','L','M','X','J','V','S']; // JS: 0 domingo ... 6 sábado
  const target=map[date.getDay()];
  const code=restOf(shift).toUpperCase().replace(/[^LMXJVSD]/g,'');
  return code.includes(target);
}

function weekendDatesForYear(year){
  const out=[];
  let d=new Date(year,0,1,12,0,0);
  while(d.getFullYear()===year){
    const day=d.getDay();
    if(day===0 || day===6) out.push(new Date(d));
    d.setDate(d.getDate()+1);
  }
  return out;
}

function fillWeekendDates(syncToCalendar=true){
  const mainDate=selectedDate();

  if(syncToCalendar && mainDate){
    const y=mainDate.getFullYear();
    if(y>=2026 && y<=2100) $('#weekendYear').value=String(y);
  }

  const year=Number($('#weekendYear').value);
  const sel=$('#weekendDate');
  const dates=weekendDatesForYear(year);

  sel.innerHTML=dates.map(d=>{
    const isoDate=iso(d);
    const label=new Intl.DateTimeFormat('es-ES',{
      weekday:'long',day:'2-digit',month:'long'
    }).format(d);
    return `<option value="${isoDate}">${label}</option>`;
  }).join('');

  if(syncToCalendar && mainDate && mainDate.getFullYear()===year){
    // Si la fecha principal es sábado o domingo, seleccionar ese mismo día.
    // Si es laborable, seleccionar el próximo sábado o domingo del calendario.
    let target=dates.find(d=>iso(d)>=iso(mainDate));
    if(!target) target=dates[dates.length-1];
    if(target) sel.value=iso(target);
  }

  renderWeekendRests();
}
function renderWeekendRests(){
  const v=$('#weekendDate').value;
  if(!v) return;
  const d=new Date(v+'T12:00:00');
  const people=PEOPLE
    .map(p=>({...p,...projected(p,d)}))
    .filter(p=>restCodeForDay(p.shift,d));

  const dayLabel=new Intl.DateTimeFormat('es-ES',{
    weekday:'long',day:'numeric',month:'long',year:'numeric'
  }).format(d);

  $('#weekendRestSummary').textContent=
    `${dayLabel} · ${people.length} descansos`;

  $('#weekendRestList').innerHTML=people.length
    ? people.map(p=>`
      <div class="weekendRestPerson">
        <div class="name">${p.name}</div>
        <div class="meta">
          <b>Conductor ${p.driver}</b> · Orden ${p.order} ·
          <b>Servicio ${p.service}</b> ·
          <span class="badge ${badgeClass(p.shift)}">${String(p.shift||'').replace(/^[MT]\s*/,'')}</span>
        </div>
      </div>`).join('')
    : '<div class="empty">No aparecen descansos para este día.</div>';
}

function render(){
  const d=selectedDate(); const q=$('#q').value.trim().toLocaleUpperCase('es');
  const serviceRaw=($('#dayServiceSearch')?.value||'').trim();
  const serviceWanted=serviceRaw==='' ? null : Number(serviceRaw);
  let rows=PEOPLE.map(p=>({...p,...projected(p,d),onVacation:isDriverOnVacation(p.driver,d),correturnoFrom:null}));
  const validServiceSearch=serviceWanted!==null && Number.isInteger(serviceWanted) && serviceWanted>=1 && serviceWanted<=116;
  if(validServiceSearch){
    const owner=effectiveServiceOwner(serviceWanted,d);
    rows=owner?[{
      ...owner.person,
      service:serviceWanted,
      shift:owner.shift,
      onVacation:isDriverOnVacation(owner.person.driver,d),
      correturnoFrom:owner.correturno?owner.baseService:null
    }]:[];
  }
  rows=rows.filter(p=>{
    const okq=!q || p.name.toLocaleUpperCase('es').includes(q)||String(p.driver).includes(q)||String(p.order)===q;
    const t=typeOf(p.shift);
    const okf=filter==='ALL'||((filter==='M'||filter==='T')&&t===filter&&!restCodeForDay(p.shift,d))||(filter==='REST'&&restCodeForDay(p.shift,d))||(filter==='VAC'&&p.onVacation);
    return okq&&okf;
  });
  // La lista principal siempre se muestra por número de conductor, de menor a mayor.
  rows.sort((a,b)=>Number(a.driver)-Number(b.driver));
  const serviceSearchActive=serviceWanted!==null && Number.isInteger(serviceWanted) && serviceWanted>=1 && serviceWanted<=116;
  listEl.innerHTML=rows.length?rows.map(p=>`
   <div class="card ${p.onVacation?'vacation':''}" data-order="${p.order}">
    <div>
      <div class="name">${p.name}${p.onVacation?'<span class="vacBadge">VACACIONES</span>':''}</div>
      <div class="meta"><span class="metaStrong">Conductor ${p.driver}</span> · Orden ${p.order} · <span class="metaStrong">Servicio ${p.service}</span>${p.correturnoFrom?` · <span class="metaStrong">CORRETURNO desde ${p.correturnoFrom}</span>`:''}</div>
    </div>
    <div class="badge ${badgeClass(p.shift)}">${['M','T'].includes(p.shift)?'':p.shift}</div>
   </div>`).join(''):(serviceSearchActive?`<div class="empty">No hay ningún conductor asignado al servicio ${serviceWanted} en esta fecha.</div>`:`<div class="empty">No hay resultados.</div>`);
  const all=PEOPLE.map(p=>projected(p,d).shift);
  document.querySelectorAll('.card').forEach(c=>c.onclick=()=>openPerson(Number(c.dataset.order)));
}

function openPerson(order){
 const p=PEOPLE.find(x=>x.order===order); const d=selectedDate(); const pr=projected(p,d);
 $('#pname').textContent=p.name;
 $('#pmeta').innerHTML=`<span class="metaStrong">Conductor ${p.driver}</span> · Orden ${p.order} · <span class="metaStrong">Servicio ${pr.service}</span>`;
$('#vacationBanner').style.display = isDriverOnVacation(p.driver,d) ? 'block' : 'none';
 $('#pshift').textContent=pr.shift;
 $('#pdate').textContent=fmt(d);
 let html='';
 const weekData=[];
 for(let i=0;i<=3;i++){
   let x=new Date(d);x.setDate(x.getDate()+7*i);
   let z=projected(p,x);
   weekData.push({date:new Date(x),service:z.service,shift:z.shift});
   html+=`<div class="week${i===0?' active':''}" role="button" tabindex="0" data-week-index="${i}"><small>${i===0?'Fecha elegida':'+'+i+' semana'+(i>1?'s':'')}</small><b>${z.shift}</b><small>Servicio ${z.service}</small></div>`;
 }
 $('#weeks').innerHTML=html;
 const btn=$('#serviceBtn'), box=$('#serviceDetail');
 let detailService=pr.service;
 let detailDate=new Date(d);
 const openServiceDetail=(service,date,weekIndex)=>{
   detailService=service;
   detailDate=new Date(date);
   const selectedWeek=weekData[weekIndex];
   if(selectedWeek){
     $('#pmeta').innerHTML=`<span class="metaStrong">Conductor ${p.driver}</span> · Orden ${p.order} · <span class="metaStrong">Servicio ${selectedWeek.service}</span>`;
     $('#pshift').textContent=selectedWeek.shift;
     $('#pdate').textContent=fmt(selectedWeek.date);
     $('#vacationBanner').style.display = isDriverOnVacation(p.driver,selectedWeek.date) ? 'block' : 'none';
   }
   btn.textContent='Servicio '+detailService+' · ver detalle';
   box.style.display='block';
   document.querySelectorAll('#weeks .week').forEach((w,idx)=>w.classList.toggle('active',idx===weekIndex));
   const initialDay=serviceDayForDate(detailDate);
   showServiceDay(detailService,initialDay);
   renderPersonServiceSheetAction(detailService,detailDate);
   document.querySelectorAll('#serviceDayTabs .serviceDayTab').forEach(tab=>{
     tab.onclick=()=>showServiceDay(detailService,tab.dataset.serviceDay);
   });
 };
 btn.textContent='Servicio '+detailService+' · ver detalle';
 box.style.display='none';
 btn.onclick=()=>{
   const opening=box.style.display==='none';
   box.style.display=opening?'block':'none';
   if(opening) openServiceDetail(detailService,detailDate,weekData.findIndex(w=>w.service===detailService && w.date.getTime()===detailDate.getTime()));
 };
 document.querySelectorAll('#weeks .week').forEach((weekEl,idx)=>{
   const activate=()=>openServiceDetail(weekData[idx].service,weekData[idx].date,idx);
   weekEl.onclick=activate;
   weekEl.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate();}};
 });
 $('#modal').classList.add('show');
}

